// ---------------------------------------------------------------------------------------
// Rust: the tvremote-ffi crate (../rust) is built with cargo-ndk for each ABI, and its
// Kotlin bindings are generated by uniffi-bindgen from a host build of the same crate.
// The Rust toolchain is the one under ~/Android/rust unless CARGO_HOME/RUSTUP_HOME say
// otherwise (see README).

val rustDir: File = rootProject.file("rust")
val coreDir: File = rootProject.file("../tv-remote-android-core/core")
val androidRoot = File(System.getProperty("user.home"), "Android")
val cargoHome: String = providers.environmentVariable("CARGO_HOME").orNull ?: "$androidRoot/rust/cargo"
val rustupHome: String = providers.environmentVariable("RUSTUP_HOME").orNull ?: "$androidRoot/rust/rustup"
// -PrustAbis=arm64-v8a builds one ABI only (faster while developing on a phone).
val rustAbis: List<String> = (providers.gradleProperty("rustAbis").orNull ?: "arm64-v8a,armeabi-v7a,x86_64")
    .split(',').map { it.trim() }.filter { it.isNotEmpty() }
val appMinSdk = 26

/** Shared by the Rust tasks: where the crate is, its sources, and the toolchain env. */
abstract class RustTask : DefaultTask() {
    @get:InputFiles
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val sources: ConfigurableFileCollection

    @get:Internal
    abstract val crateDir: DirectoryProperty

    @get:Input
    abstract val toolEnv: MapProperty<String, String>

    @get:Inject
    abstract val exec: ExecOperations

    protected fun cargo(vararg args: String) {
        val env = toolEnv.get()
        exec.exec {
            workingDir = crateDir.get().asFile
            environment(env)
            environment("PATH", "${env.getValue("CARGO_HOME")}/bin:${System.getenv("PATH")}")
            commandLine(listOf("${env.getValue("CARGO_HOME")}/bin/cargo") + args)
        }
    }
}

/** `cargo ndk build --release` → <outputDir>/<abi>/libtvremote_ffi.so. */
abstract class CargoNdkTask : RustTask() {
    @get:Input
    abstract val abis: ListProperty<String>

    @get:Input
    abstract val platform: Property<Int>

    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @TaskAction
    fun build() {
        val out = outputDir.get().asFile
        out.deleteRecursively()
        out.mkdirs()
        val targets = abis.get().flatMap { listOf("-t", it) }.toTypedArray()
        cargo("ndk", *targets, "-P", platform.get().toString(), "-o", out.absolutePath, "build", "--release", "--lib")
    }
}

/** uniffi-bindgen (same uniffi version as the crate) on a host build → Kotlin sources. */
abstract class UniffiBindgenTask : RustTask() {
    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @TaskAction
    fun generate() {
        val out = outputDir.get().asFile
        out.deleteRecursively()
        out.mkdirs()
        cargo("build", "--lib")
        val lib = crateDir.get().asFile.resolve("target/debug/libtvremote_ffi.so")
        cargo(
            "run", "--quiet", "--features", "bindgen", "--bin", "uniffi-bindgen", "--",
            "generate", "--library", lib.absolutePath, "--language", "kotlin",
            "--out-dir", out.absolutePath, "--no-format",
        )
    }
}

val rustSources = files(
    fileTree(rustDir) { include("Cargo.toml", "Cargo.lock", "uniffi.toml", "src/**") },
    fileTree(coreDir) { include("Cargo.toml", "src/**") },
)

android {
    namespace = "fr.ryoku.tvremote"
    compileSdk = 37
    ndkVersion = "29.0.14206865"

    defaultConfig {
        applicationId = "fr.ryoku.tvremote"
        minSdk = appMinSdk
        targetSdk = 37
        versionCode = 1
        versionName = "0.1.0"
        // Only the ABIs the Rust library is built for (JNA ships more).
        ndk { abiFilters += rustAbis }
    }

    buildTypes {
        release {
            isMinifyEnabled = false
        }
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    buildFeatures {
        compose = true
    }
}

val rustToolEnv = androidComponents.sdkComponents.ndkDirectory.map { ndk ->
    mapOf(
        "CARGO_HOME" to cargoHome,
        "RUSTUP_HOME" to rustupHome,
        "ANDROID_NDK_HOME" to ndk.asFile.absolutePath,
        // The user's environment may point `cargo install` elsewhere; irrelevant here
        // but keep cargo self-contained.
        "CARGO_INSTALL_ROOT" to cargoHome,
    )
}

val cargoNdk = tasks.register<CargoNdkTask>("cargoNdkBuild") {
    group = "rust"
    description = "Builds libtvremote_ffi.so for $rustAbis with cargo-ndk."
    sources.from(rustSources)
    crateDir.set(rustDir)
    toolEnv.set(rustToolEnv)
    abis.set(rustAbis)
    platform.set(appMinSdk)
    outputDir.set(layout.buildDirectory.dir("rust/jniLibs"))
}

val uniffiBindings = tasks.register<UniffiBindgenTask>("uniffiBindgen") {
    group = "rust"
    description = "Generates the Kotlin bindings of tvremote-ffi."
    sources.from(rustSources)
    crateDir.set(rustDir)
    toolEnv.set(rustToolEnv)
    outputDir.set(layout.buildDirectory.dir("generated/uniffi/kotlin"))
}

androidComponents {
    onVariants { variant ->
        variant.sources.jniLibs?.addGeneratedSourceDirectory(cargoNdk, CargoNdkTask::outputDir)
        variant.sources.kotlin?.addGeneratedSourceDirectory(uniffiBindings, UniffiBindgenTask::outputDir)
    }
}

